   "ess1_12": [{ q: "Which word means 'a person who paints, draws, or sculpts'?", o: ["magazine", "article", "artist", "alone"], a: "artist" }, { q: "Which word means 'to decide that something is good or bad'?", o: ["neighbor", "judge", "meal", "compare"], a: "judge" }, { q: "Which word means 'a way of doing something'?", o: ["method", "profit", "professional", "attitude"], a: "method" }, { q: "Which word means 'how good something is'?", o: ["apartment", "thin", "quality", "stairs"], a: "quality" }, { q: "Which word means 'something used to make other things'?", o: ["shape", "symbol", "material", "space"], a: "material" }, { q: "I don't like the person who lives near me. (Which word starting with 'neigh-' is a synonym for 'the person who lives near me'?)", o: ["neighbor", "neighborhood", "neither", "nephew"], a: "neighbor" }, { q: "I read a regular publication about sports. (Which word starting with 'maga-' means 'a regular publication'?)", o: ["magazine", "magnify", "magic", "magnet"], a: "magazine" }, { q: "The doctor gave his expert and qualified advice. (Which word starting with 'profe-' means 'expert and qualified'?)", o: ["professional", "professor", "profession", "profound"], a: "professional" }, { q: "He looked at the differences between two books. (Which word starting with 'co-' means 'to look at the differences between things'?)", o: ["compare", "command", "comfort", "combine"], a: "compare" }, { q: "She has a good way of thinking about things. (Which word starting with 'a-' means 'a way of thinking or feeling about something'?)", o: ["attitude", "apartment", "article", "alone"], a: "attitude" }],
